{
  "state": [
    {"name": "head", "width": 2, "next": "rst ? 0 : (read_accepted ? ((head + 1) % DEPTH) : head)"},
    {"name": "tail", "width": 2, "next": "rst ? 0 : (write_accepted ? ((tail + 1) % DEPTH) : tail)"},
    {"name": "count", "width": 3, "next": "rst ? 0 : (count + (write_accepted ? 1 : 0) - (read_accepted ? 1 : 0))"}
  ],
  "defs": [
    {"name": "is_empty", "width": 1, "expr": "count == 0"},
    {"name": "is_full", "width": 1, "expr": "count == DEPTH"},
    {"name": "read_accepted", "width": 1, "expr": "rd_en && !is_empty"},
    {"name": "write_accepted", "width": 1, "expr": "wr_en && !is_full"}
  ],
  "memories": [
    {"name": "mem", "width": 8, "depth": 4}
  ],
  "writes": [
    {"memory": "mem", "when": "write_accepted", "index": "tail", "value": "din"}
  ],
  "properties": [
    {"id": "full_matches", "when": "1", "then": "full == is_full", "why": "full output must reflect occupancy before the edge"},
    {"id": "empty_matches", "when": "1", "then": "empty == is_empty", "why": "empty output must reflect occupancy before the edge"},
    {"id": "dout_after_read", "when": "$past(read_accepted)", "then": "dout == $past(mem[$past(head)])", "why": "after an accepted read, dout must equal the word that was at the head before the edge"}
  ],
  "notes": "Fixed dout_after_read to use $past(head) for the head index at the time of the accepted read."
}

